## The Corrected Code

*I'll put a girdle round about this code in forty minutes!*

```go
package cache

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

type CacheEntry struct {
    Value     interface{}
    ExpiresAt time.Time
    loading   chan struct{} // Signals load completion
    err       error         // Stores load error
}

type LoadFunc func(ctx context.Context, key string) (interface{}, error)

type Cache struct {
    data   map[string]*CacheEntry
    mu     sync.RWMutex
    ttl    time.Duration
    loader LoadFunc
    stats  Stats
}

type Stats struct {
    Hits       int64
    Misses     int64
    LoadErrors int64
}

func NewCache(ttl time.Duration, loader LoadFunc) *Cache {
    c := &Cache{
        data:   make(map[string]*CacheEntry),
        ttl:    ttl,
        loader: loader,
    }
    go c.cleanupLoop()
    return c
}

func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    // Fast path with read lock
    c.mu.RLock()
    entry, ok := c.data[key]
    if ok && entry.loading == nil && time.Now().Before(entry.ExpiresAt) {
        c.mu.RUnlock()
        atomic.AddInt64(&c.stats.Hits, 1)
        return entry.Value, nil
    }
    c.mu.RUnlock()

    // Slow path with write lock
    c.mu.Lock()
    entry, ok = c.data[key]

    if ok {
        if entry.loading == nil && time.Now().Before(entry.ExpiresAt) {
            c.mu.Unlock()
            atomic.AddInt64(&c.stats.Hits, 1)
            return entry.Value, nil
        }
        if entry.loading != nil {
            loading := entry.loading
            c.mu.Unlock()
            return c.waitForLoad(ctx, key, loading)
        }
    }

    // Create loading entry with channel
    loading := make(chan struct{})
    c.data[key] = &CacheEntry{loading: loading}
    c.mu.Unlock()

    atomic.AddInt64(&c.stats.Misses, 1)

    value, err := c.loader(ctx, key)

    c.mu.Lock()
    if err != nil {
        atomic.AddInt64(&c.stats.LoadErrors, 1)
        c.data[key] = &CacheEntry{loading: nil, err: err, ExpiresAt: time.Now().Add(time.Second)}
    } else {
        c.data[key] = &CacheEntry{
            Value:     value,
            ExpiresAt: time.Now().Add(c.ttl),
            loading:   nil,
        }
    }
    close(loading) // Signal all waiters!
    c.mu.Unlock()

    return value, err
}

func (c *Cache) waitForLoad(ctx context.Context, key string, loading chan struct{}) (interface{}, error) {
    select {
    case <-ctx.Done():
        return nil, ctx.Err()
    case <-loading:
        c.mu.RLock()
        entry, ok := c.data[key]
        c.mu.RUnlock()
        if !ok {
            return nil, context.Canceled
        }
        if entry.err != nil {
            return nil, entry.err
        }
        return entry.Value, nil
    }
}

func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data[key] = &CacheEntry{
        Value:     value,
        ExpiresAt: time.Now().Add(c.ttl),
    }
}

func (c *Cache) Invalidate(key string) {
    c.mu.Lock()
    defer c.mu.Unlock()
    delete(c.data, key)
}

func (c *Cache) InvalidateAll() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data = make(map[string]*CacheEntry)
}

func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    results := make(map[string]interface{})
    var mu sync.Mutex
    var wg sync.WaitGroup

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            value, err := c.Get(ctx, k)
            if err == nil {
                mu.Lock()
                results[k] = value
                mu.Unlock()
            }
        }(key)
    }
    wg.Wait()
    return results
}

func (c *Cache) cleanupLoop() {
    ticker := time.NewTicker(time.Minute)
    defer ticker.Stop()
    for range ticker.C {
        c.cleanup()
    }
}

func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()
    now := time.Now()
    for key, entry := range c.data {
        if entry.loading == nil && now.After(entry.ExpiresAt) {
            delete(c.data, key)
        }
    }
}

func (c *Cache) Size() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return len(c.data)
}

func (c *Cache) GetStats() Stats {
    return Stats{
        Hits:       atomic.LoadInt64(&c.stats.Hits),
        Misses:     atomic.LoadInt64(&c.stats.Misses),
        LoadErrors: atomic.LoadInt64(&c.stats.LoadErrors),
    }
}

func (c *Cache) Refresh(ctx context.Context, key string) error {
    value, err := c.loader(ctx, key)
    if err != nil {
        return err
    }
    c.Set(key, value)
    return nil
}

func (c *Cache) LoadOrStore(ctx context.Context, key string, loader LoadFunc) (interface{}, error) {
    return c.Get(ctx, key) // Reuse Get's proper locking
}
```

